/** User-initiated, pinned upstream downloads. Android's installer remains the final explicit step. */
final class IconPackDownloads {
 static final class Pack {final String id,title,pkg,url,sha;final long size;Pack(String id,String title,String pkg,String path,String sha,long size){this.id=id;this.title=title;this.pkg=pkg;url="https://github.com/"+path;this.sha=sha;this.size=size;}}
 static final Pack[] PACKS={
  new Pack("projectivy","Projectivy Icon Pack · 1.1.9","dev.projectivy.blueprint.app","SicMundus86/ProjectivyIconPack/releases/download/1.1.9/Projectivy_Icon_Pack_1.1.9.apk","c3343564f6ff7a5ab51542a086f52820997fadbf26d947c1d30c3ef7bdad2d83",17139097),
  new Pack("minimalist","Android TV Minimalist · 1.0.0","com.hqnscl.minimalist.app","hqn-scl/android-tv-minimalist-icon-pack/releases/download/v1.0.0/Minimalist-Icons.1.0.0.apk","f8ba6e5bef882a8e5f440bc98ff33f63ba5dbcbf49826ff973440ce37a9fe08d",18741299),
  new Pack("glitch","Glitch Reflections TV · 2.0.2","dev.glitchreflections.tv","MYKLHARU/glitch-icons/releases/download/v1.0.1/Glitch-Reflections-TV-2.0.2.apk","0a51e37f2c9fc95c7bf9569b8b5596c1b9ed814438f5a0c16e0ad45648b7b203",228012634)};
 static void show(Activity a){SettingsSheet p=new SettingsSheet(a,"Icon-Packs herunterladen");p.info("Original-APKs der drei gewählten GitHub-Projekte. Du wählst Download und Installation selbst. Animierte APNG-Icons erscheinen in unserem Launcher als Standbild.");for(Pack pack:PACKS)p.row("grid",pack.title,String.format(Locale.GERMANY,"%.1f MB · Original-Download",pack.size/1000000d),()->new Transfer(a,pack));p.show();}
 private static final class Transfer {
  final Activity a;final Pack pack;final SettingsSheet sheet;final TextView status;final TextView progress;final ExecutorService worker=Executors.newSingleThreadExecutor();final File file,partial;volatile boolean closed,downloading,verified;
  Transfer(Activity a,Pack pack){this.a=a;this.pack=pack;File directory=a.getExternalFilesDir("iconpacks");if(directory==null){Toast.makeText(a,"App-Speicher nicht verfügbar",Toast.LENGTH_LONG).show();sheet=null;status=null;progress=null;file=partial=null;worker.shutdownNow();return;}if(!directory.isDirectory())directory.mkdirs();file=new File(directory,pack.id+".apk");partial=new File(directory,pack.id+".pending.apk");sheet=new SettingsSheet(a,pack.title);status=GlassDialog.text(a,"Noch nicht heruntergeladen",13);progress=GlassDialog.text(a,"",11);LinearLayout details=new LinearLayout(a);details.setOrientation(LinearLayout.VERTICAL);details.addView(status);details.addView(progress);sheet.preview(details,90);
   sheet.row("video","Herunterladen",String.format(Locale.GERMANY,"%.1f MB · SHA-256 wird geprüft",pack.size/1000000d),this::download);
   sheet.row("grid","Installieren","Öffnet die Android-Bestätigung; installiert nicht automatisch",this::install);
   sheet.row("settings","Installation aus dieser Quelle erlauben","Android-Einstellung für unseren Launcher",this::allow);
   sheet.row("eye","GitHub-Quelle anzeigen",pack.url.substring(0,pack.url.indexOf("/download/")),()->{try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(pack.url.substring(0,pack.url.indexOf("/download/")))));}catch(ActivityNotFoundException e){Toast.makeText(a,pack.url,Toast.LENGTH_LONG).show();}});
   sheet.info("Bleibe für den Download auf dieser Seite. Zurück bricht einen laufenden Download ab. Nach der Installation unter Icon-Packs die Liste aktualisieren.");sheet.dialog.setOnDismissListener(d->{closed=true;worker.shutdownNow();});sheet.show();if(file.isFile()){status.setText("Vorhandene Datei wird geprüft …");worker.execute(()->{boolean valid=verify(file);a.runOnUiThread(()->{if(!closed){verified=valid;status.setText(valid?"Download geprüft · bereit zur Installation":"Datei unvollständig · erneut herunterladen");}});});}}
  private boolean verify(File candidate){try{if(candidate.length()!=pack.size)return false;MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(candidate)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())return false;hash.update(buffer,0,n);}}StringBuilder hex=new StringBuilder();for(byte b:hash.digest())hex.append(String.format(Locale.ROOT,"%02x",b));if(!pack.sha.equals(hex.toString()))return false;PackageInfo info=a.getPackageManager().getPackageArchiveInfo(candidate.getAbsolutePath(),0);return info!=null&&pack.pkg.equals(info.packageName);}catch(Exception e){return false;}}
  private void download(){if(downloading||closed)return;if(file.getParentFile().getUsableSpace()<pack.size+20*1024*1024){status.setText("Für diesen Download ist nicht genug Speicher frei");return;}downloading=true;verified=false;status.setText("Download läuft …");worker.execute(()->{String result;HttpURLConnection request=null;try{request=(HttpURLConnection)new URL(pack.url).openConnection();request.setConnectTimeout(15000);request.setReadTimeout(15000);request.setRequestProperty("User-Agent","TvHome-IconPack/1.0");if(request.getResponseCode()!=200||!request.getURL().getProtocol().equals("https"))throw new IOException("Download nicht verfügbar");long length=0,last=0;try(InputStream in=request.getInputStream();OutputStream out=new FileOutputStream(partial)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){if(closed||Thread.currentThread().isInterrupted())throw new InterruptedIOException();length+=n;if(length>pack.size)throw new IOException("Datei größer als erwartet");out.write(buffer,0,n);long now=android.os.SystemClock.elapsedRealtime();if(now-last>250){last=now;final long done=length;a.runOnUiThread(()->{if(!closed)progress.setText(String.format(Locale.GERMANY,"%.1f / %.1f MB · %d %%",done/1000000d,pack.size/1000000d,done*100/pack.size));});}}}if(!verify(partial))throw new IOException("Hash oder Paketname stimmt nicht");if(file.exists()&&!file.delete())throw new IOException("Alte Download-Datei nicht ersetzbar");if(!partial.renameTo(file))throw new IOException("Download nicht speicherbar");verified=true;result="Download geprüft · bereit zur Installation";}catch(Exception e){partial.delete();result="Download fehlgeschlagen · "+e.getMessage();}finally{if(request!=null)request.disconnect();}String message=result;a.runOnUiThread(()->{downloading=false;if(!closed){status.setText(message);if(verified)progress.setText(String.format(Locale.GERMANY,"%.1f / %.1f MB · 100 %%",pack.size/1000000d,pack.size/1000000d));}});});}
  private void allow(){try{a.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+a.getPackageName())));}catch(ActivityNotFoundException e){Toast.makeText(a,R.string.not_available,Toast.LENGTH_LONG).show();}}
  private void install(){if(!verified){status.setText("Zuerst den Download abschließen und prüfen lassen");return;}if(!a.getPackageManager().canRequestPackageInstalls()){status.setText("Bitte zuerst Installation aus dieser Quelle erlauben");return;}try{Uri uri=FileProvider.getUriForFile(a,a.getPackageName()+".iconpack-files",file);Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);a.startActivity(intent);}catch(ActivityNotFoundException|SecurityException e){status.setText("Android-Installer nicht verfügbar");}}
 }
}
